using System.Collections.Generic;
using System;
using System.IO;
using MassiveArmy.Industrial;
class Program {
 static int checks;static void Check(bool ok,string name){if(!ok)throw new Exception(name);checks++;Console.WriteLine("PASS "+name);}
 static IndustrialCommand C(long n,string kind,long source=0,long target=0,string item=null,long count=0,string definition=null)=>new IndustrialCommand{sequence=n,kind=kind,source=source,target=target,item=item,count=count,definition=definition,pose=new FramePose{body=1}};
 static string Canonical(IndustrialWorld world)=>IndustrialAuthority.Snapshot(IndustrialAuthority.Restore(IndustrialAuthority.Snapshot(world)));
 static void Main(){
 var lot=new MaterialLot{litres=101,iron=19,copper=7,radioactive=2,activity=10};var start=lot;var gathered=new MaterialLot();while(lot.litres>0)gathered.Add(lot.Take(Math.Min(3,lot.litres)));Check(gathered.litres==start.litres&&gathered.iron==start.iron&&gathered.activity==start.activity,"Split/merge conserves volume, grade and activity");
 var pile=new DirtPile();pile.Add(start);long cells=0;foreach(var x in pile.cells)cells+=x;Check(cells==101,"Pile mesh cells conserve litres");var extracted=pile.Scoop(101);Check(extracted.activity==10&&pile.material.litres==0,"Scooping preserves activity");
 var a=new Inventory{capacity=10};var b=new Inventory{capacity=1};a.Add("radioactive-ore",2,11);Check(Inventory.Transfer(a,b,"radioactive-ore",1)&&b.items[0].activity==5.5,"Transfers preserve source activity");Check(!Inventory.Transfer(a,b,"radioactive-ore",1)&&a.Count("radioactive-ore")==1,"Full destination cannot consume input");
 var w=new IndustrialWorld();var actor=w.Register(1,new FramePose{body=1});actor.inventory.Add("foundry-kit",1);var command=C(1,"place",definition:"foundry");var result=w.Execute(1,command);Check(result.accepted&&w.machines.Count==1,"Paid construction");long stone=actor.inventory.Count("stone");Check(!w.Execute(1,command).accepted&&actor.inventory.Count("stone")==stone,"Replay cannot double-spend or duplicate construction");Check(!w.Execute(2,command).accepted,"Unknown actor rejected");
 command=C(2,"place",definition:"store");command.pose.x=double.NaN;Check(!w.Execute(1,command).accepted,"Nonfinite position rejected");
 var gen=new IndustrialMachine{id=w.AllocateId(),owner=1,definition="generator",pose=new FramePose{body=1,x=8}};gen.input.Add("fuel",1);w.machines.Add(gen);var foundry=w.machines[0];foundry.powerSource=gen.id;foundry.input.Add("iron-ore",4);for(int i=0;i<30;i++)w.Step();Check(foundry.output.Count("iron-bar")==2&&foundry.output.Count("slag")==2,"Foundry produces paid reserved outputs");Check(gen.progress==70,"Last fuel unit supplies a complete fuel period");
 var store=new IndustrialMachine{id=w.AllocateId(),owner=1,definition="store",pose=new FramePose{body=1,x=4},input=new Inventory{capacity=1}};w.machines.Add(store);w.belts.Add(new ConveyorLane{id=w.AllocateId(),source=foundry.id,target=store.id,length=1,filter="iron-bar"});for(int i=0;i<30;i++)w.Step();Check(store.input.Count("iron-bar")==1&&w.belts[0].items.Count==1,"Belt filters and backpressure preserve remaining item");
 var before=IndustrialAuthority.Snapshot(w);var clone=IndustrialAuthority.Restore(before);Check(clone.belts[0].items.Count==1&&clone.tick==w.tick,"Save roundtrip retains in-flight items and clock");
 string path=Path.GetFullPath("TestResults/Industrial/recovery.xml");if(File.Exists(path))File.Delete(path);if(File.Exists(path+".journal"))File.Delete(path+".journal");using(var auth=new IndustrialAuthority(w,path)){auth.Save();actor.pose=store.pose;var put=C(2,"withdraw-item",source:store.id,item:"iron-bar",count:1);Check(auth.Execute(1,put).accepted,"Journalled authoritative transfer");auth.Step(2);}
 var recovered=IndustrialAuthority.Load(path);Check(recovered.Actor(1).inventory.Count("iron-bar")==1&&recovered.Machine(store.id).input.Count("iron-bar")==w.Machine(store.id).input.Count("iron-bar"),"Crash recovery replays transfer once");Check(recovered.tick==w.tick,"Crash recovery replays simulation time");Check(!recovered.Execute(1,C(2,"withdraw-item",source:store.id,item:"iron-bar",count:1)).accepted,"Recovered sequence rejects replay");
 var shielded=new IndustrialWorld();var person=shielded.Register(1,new FramePose{body=1});var box=new IndustrialMachine{id=shielded.AllocateId(),definition="shielded-store",owner=1,pose=person.pose};box.input.Add("isotope",1);shielded.machines.Add(box);shielded.Step();double closed=person.exposure;box.closed=false;shielded.Step();Check(person.exposure>closed*90,"Opening shielding raises radiation exposure");for(int i=0;i<10000;i++)shielded.Step();Check(person.health==0,"Sustained radiation can kill");
 var netWorld=new IndustrialWorld();netWorld.Register(1,new FramePose{body=1}).inventory.Add("store-kit",1);netWorld.Register(2,new FramePose{body=1}).inventory.Add("store-kit",1);using(var authority=new IndustrialAuthority(netWorld))using(var gateway=new IndustrialLoopbackGateway(authority,new System.Collections.Generic.Dictionary<string,long>{{"first",1},{"second",2}})){
 var one=System.Threading.Tasks.Task.Run(()=>IndustrialLoopbackGateway.Send(gateway.Port,"first",C(1,"place",definition:"store")));
 var two=System.Threading.Tasks.Task.Run(()=>IndustrialLoopbackGateway.Send(gateway.Port,"second",C(1,"place",definition:"store")));
 System.Threading.Tasks.Task.WaitAll(one,two);Check(one.Result.accepted!=two.Result.accepted&&netWorld.machines.Count==1,"Two real loopback clients cannot double-place occupied construction");
 Check(!IndustrialLoopbackGateway.Send(gateway.Port,"unknown",C(1,"place",definition:"store")).accepted,"Unknown network ticket rejected");
 }
 var line=new IndustrialWorld();var operator1=line.Register(1,new FramePose{body=1});
 IndustrialMachine Machine(string type,double x){var m=new IndustrialMachine{id=line.AllocateId(),owner=1,definition=type,recipe=IndustrialCatalog.Machines[type].recipe,pose=new FramePose{body=1,x=x},input=new Inventory{capacity=10000},output=new Inventory{capacity=10000}};line.machines.Add(m);return m;}
 var power=Machine("generator",-2);power.input.Add("fuel",30);var pump=Machine("pump",0);pump.input.Add("water",1000);var wash=Machine("sluice",2);wash.input.bulk=new MaterialLot{litres=1000,iron=200};var furnace=Machine("foundry",4);var press=Machine("press",6);var finished=Machine("store",8);pump.waterTarget=wash.id;foreach(var m in line.machines)m.powerSource=power.id;
 void Belt(IndustrialMachine f,IndustrialMachine t,string filter){line.belts.Add(new ConveyorLane{id=line.AllocateId(),owner=1,source=f.id,target=t.id,length=2,filter=filter});}
 Belt(wash,furnace,"iron-ore");Belt(furnace,press,"iron-bar");Belt(press,finished,"plate");for(int i=0;i<2200;i++)line.Step();
 Check(finished.input.Count("plate")==100,"Complete dirt-to-washing-to-foundry-to-press-to-storage conveyor chain");
 long material=0;foreach(var m in line.machines){material+=m.input.bulk.litres;foreach(var stack in m.input.items)if(stack.item!="fuel"&&stack.item!="water")material+=stack.count;foreach(var stack in m.output.items)material+=stack.count;foreach(var stack in m.reserved)material+=stack.count;}foreach(var belt in line.belts)material+=belt.items.Count;Check(material==1000,"End-to-end processing conserves ore, products and waste");
 Check(pump.input.Count("water")+wash.water<1000,"Washing consumes finite supplied water");
 var hazard=new IndustrialWorld();var hg=new IndustrialMachine{id=1,definition="generator"};hg.input.Add("fuel",5);var hw=new IndustrialMachine{id=2,definition="sluice",recipe="wash",water=100,powerSource=1,input=new Inventory{capacity=2000},output=new Inventory{capacity=2000}};hw.input.bulk=new MaterialLot{litres=100,iron=20,radioactive=5,activity=25};hazard.machines.Add(hg);hazard.machines.Add(hw);for(int i=0;i<10;i++)hazard.Step();double activity=0;long amount=0;foreach(var item in hw.output.items){activity+=item.activity;amount+=item.count;}Check(activity==25&&amount==100,"Sluice partitions radiation into ore and tailings without laundering it");
 var blocked=new IndustrialWorld();var bg=new IndustrialMachine{id=1,definition="generator"};bg.input.Add("fuel",2);var bf=new IndustrialMachine{id=2,definition="foundry",recipe="iron",powerSource=1,output=new Inventory{capacity=1}};bf.input.Add("iron-ore",4);blocked.machines.Add(bg);blocked.machines.Add(bf);blocked.Step();Check(bf.input.Count("iron-ore")==4&&bf.status=="Output blocked","Blocked outputs do not consume recipe inputs");
 string buildPath=Path.GetFullPath("TestResults/Industrial/construction.xml");if(File.Exists(buildPath))File.Delete(buildPath);if(File.Exists(buildPath+".journal"))File.Delete(buildPath+".journal");var building=new IndustrialWorld();building.Register(1,new FramePose{body=1});using(var authority=new IndustrialAuthority(building,buildPath)){authority.Save();building.AllocateId();building.AllocateId();authority.CommitConstruction(1,1,"module fixture",2);}
 var built=IndustrialAuthority.Load(buildPath);Check(built.Actor(1).inventory.Count("stone")==62&&built.buildStates.Count==1&&built.nextId==3,"Construction payment, data and ID allocator recover atomically");File.AppendAllText(buildPath+".journal","incomplete crash tail");var tail=IndustrialAuthority.Load(buildPath);Check(tail.Actor(1).inventory.Count("stone")==62,"Recovery discards only an unterminated journal tail");using(var authority=new IndustrialAuthority(tail,buildPath))authority.Step();Check(IndustrialAuthority.Load(buildPath).tick==1,"Recovered journal remains appendable");
 var hauling=new IndustrialWorld();var hauler=hauling.Register(1,new FramePose{body=1});var stockpile=new DirtPile{id=hauling.AllocateId(),owner=1,pose=hauler.pose};stockpile.Add(new MaterialLot{litres=1000,iron=200,activity=15});hauling.piles.Add(stockpile);var truck=new IndustrialMachine{id=hauling.AllocateId(),owner=1,definition="truck",pose=hauler.pose};hauling.machines.Add(truck);
 Check(hauling.Execute(1,C(1,"bulk-transfer",stockpile.id,truck.id,count:1000)).accepted,"Bucket transfer loads a manufactured vehicle payload");Check(truck.input.bulk.iron==200&&truck.input.bulk.activity==15&&stockpile.material.litres==0,"Vehicle loading conserves grade and radioactivity");
 Check(hauling.Execute(1,C(2,"bulk-transfer",truck.id,stockpile.id,count:1000)).accepted&&stockpile.material.litres==1000,"Vehicle discharge restores the growing pile");
 var protection=new IndustrialWorld();var patient=protection.Register(1,new FramePose{body=1});patient.inventory.Add("isotope",2);patient.inventory.Add("radiation-suit",1);protection.Step();double without=patient.exposure;Check(protection.Execute(1,C(1,"protection")).accepted,"A manufactured suit can be equipped");protection.Step();Check(Math.Abs(patient.exposure-without*.25)<1e-8,"Equipped protection reduces exposure by its defined attenuation");patient.inventory.Remove("radiation-suit",1);protection.Step();Check(patient.protection==0,"Removing the suit cannot retain free shielding");patient.inventory.Add("decontamination-kit",1);patient.dose=80;Check(protection.Execute(1,C(2,"treat")).accepted&&patient.dose==60&&patient.inventory.Count("decontamination-kit")==0,"Treatment spends a manufactured kit and reduces dose");
 var dry=new IndustrialWorld();var dryGen=new IndustrialMachine{id=1,definition="generator"};dryGen.input.Add("fuel",1);var dryPump=new IndustrialMachine{id=2,definition="pump",waterTarget=3,powerSource=1};var dryTarget=new IndustrialMachine{id=3,definition="sluice",recipe="wash",powerSource=1};dry.machines.Add(dryGen);dry.machines.Add(dryPump);dry.machines.Add(dryTarget);dry.Step();Check(dryTarget.water==0,"An empty pump cannot generate free water");
 string dosePath=Path.GetFullPath("TestResults/Industrial/movement.xml");if(File.Exists(dosePath))File.Delete(dosePath);if(File.Exists(dosePath+".journal"))File.Delete(dosePath+".journal");var moving=new IndustrialWorld();var walker=moving.Register(1,new FramePose{body=1,x=20});var radiation=new IndustrialMachine{id=moving.AllocateId(),definition="store",pose=new FramePose{body=1}};radiation.input.Add("isotope",1);moving.machines.Add(radiation);using(var authority=new IndustrialAuthority(moving,dosePath)){authority.Save();walker.pose=new FramePose{body=1};walker.health=88;authority.Step(10);}var replayed=IndustrialAuthority.Load(dosePath);Check(Math.Abs(replayed.Actor(1).dose-walker.dose)<1e-8&&replayed.Actor(1).health==walker.health,"Movement and health checkpoints preserve radiation during crash replay");

 var kits=new IndustrialWorld();var crafter=kits.Register(1,new FramePose{body=1});
 Check(kits.Execute(1,C(1,"place",definition:"workbench")).accepted&&crafter.inventory.Count("stone")==60,"Machine placement pays raw resources without a kit");long bench=kits.machines[0].id;
 Check(kits.Execute(1,C(2,"pack",target:bench)).accepted&&crafter.inventory.Count("stone")==64,"Dismantling returns the actual construction resources");Check(!kits.Execute(1,C(3,"pack",target:bench)).accepted&&crafter.inventory.Count("stone")==64,"Dismantle replay cannot duplicate resources");
 Check(!kits.Execute(1,C(3,"craft",item:"workbench-kit",count:1)).accepted,"Construction kit recipes are retired");crafter.inventory.Add("iron-bar",10);Check(kits.Execute(1,C(3,"craft",item:"plate",count:1)).accepted&&crafter.inventory.Count("iron-bar")==8&&crafter.inventory.reserved==2,"Field crafting consumes metal and reserves produced components");for(int n=0;n<14;n++)kits.Step();Check(crafter.inventory.Count("plate")==0,"Material crafting has a real duration");var savedCraft=IndustrialAuthority.Restore(IndustrialAuthority.Snapshot(kits));savedCraft.Step();Check(savedCraft.Actor(1).inventory.Count("plate")==2&&savedCraft.Actor(1).inventory.reserved==0,"In-progress component crafting survives save/reload");kits.Step();
 Check(kits.Execute(1,C(4,"craft",item:"plate",count:1)).accepted&&kits.Execute(1,C(5,"cancel-craft")).accepted&&crafter.inventory.Count("iron-bar")==8,"Cancelling returns the paid metal ingredients");
 kits.mounts.Add(new IndustrialMount{site=10,module=11,owner=1,socket=2,width=2,depth=1.5f,pose=crafter.pose});var mountCommand=C(6,"place",definition:"workbench");mountCommand.attachmentSite=10;mountCommand.attachmentModule=11;mountCommand.attachmentSocket=2;Check(kits.Execute(1,mountCommand).accepted&&kits.machines[0].attachmentModule==11,"Resource-built machinery retains its building socket attachment");mountCommand.sequence=7;Check(!kits.Execute(1,mountCommand).accepted,"Occupied machine sockets still reject placement");var empty=kits.machines[0];empty.input.Add("stone",1);Check(!kits.Execute(1,C(7,"pack",target:empty.id)).accepted,"Nonempty machines cannot be dismantled and lose cargo");empty.input.Remove("stone",1);mountCommand.definition="sluice";Check(kits.PlacementError(1,mountCommand)=="Machine does not fit this socket","Resource construction retains footprint validation");
 string typedPath=Path.GetFullPath("TestResults/Industrial/typed-build.xml");if(File.Exists(typedPath))File.Delete(typedPath);if(File.Exists(typedPath+".journal"))File.Delete(typedPath+".journal");crafter.inventory.Add("plate",12);crafter.inventory.Add("gear",4);var roomCost=IndustrialCatalog.ModuleCost("WorkshopRoom");var roomPayment=IndustrialConstruction.Receipt(crafter.inventory,roomCost,false);using(var authority=new IndustrialAuthority(kits,typedPath)){authority.Save();authority.CommitConstructionResources(1,1,"workshop graph",roomPayment,false,new System.Collections.Generic.List<IndustrialMount>(kits.mounts),new System.Collections.Generic.List<IndustrialConstructionSource>());}var typed=IndustrialAuthority.Load(typedPath);Check(typed.Actor(1).inventory.Count("gear")==0&&typed.mounts.Count==1&&typed.buildStates[0].json=="workshop graph","Multi-resource room payment, sockets and construction recover atomically");
 var free=new IndustrialWorld();var builder=free.Register(1,new FramePose{body=1});builder.inventory.items.Clear();Check(!free.Execute(1,C(1,"place",definition:"foundry")).accepted,"Survival rejects construction without resources");free.Register(2,new FramePose{body=1});Check(!free.Execute(2,C(1,"creative",count:1)).accepted,"Only the world host can enable creative mode");Check(free.Execute(1,C(1,"creative",count:1)).accepted&&free.creativeMode,"Creative mode enables through an authoritative command");Check(free.Execute(1,C(2,"place",definition:"foundry")).accepted&&builder.inventory.Used==0&&free.machines[0].constructionPaid.Count==0,"Creative construction requires and spends no resources");Check(!free.Execute(1,C(3,"place",definition:"foundry")).accepted,"Creative mode retains overlap validation");Check(free.Execute(1,C(3,"creative",count:0)).accepted&&free.Execute(1,C(4,"pack",target:free.machines[0].id)).accepted&&builder.inventory.Used==0,"Free creative builds yield no resources after returning to survival");
 Check(free.Execute(1,C(5,"creative",count:1)).accepted&&free.Execute(1,C(6,"craft",item:"plate",count:2)).accepted&&builder.inventory.Used==0,"Creative crafting reserves outputs without charging ingredients");Check(free.Execute(1,C(7,"cancel-craft",target:builder.craft.id)).accepted&&builder.inventory.Used==0,"Cancelling a creative craft cannot mint ingredient refunds");Check(free.Execute(1,C(8,"creative-item",item:"iron-ore",count:100)).accepted&&builder.inventory.Count("iron-ore")==100,"Creative test supplies can be spawned into real inventories");Check(free.Execute(1,C(9,"creative-dirt",count:100)).accepted&&builder.inventory.bulk.litres==100&&builder.inventory.bulk.iron==20,"Creative pay dirt remains a measurable test material");Check(IndustrialAuthority.Restore(IndustrialAuthority.Snapshot(free)).creativeMode,"Creative world setting survives save/reload");
 string creativePath=Path.GetFullPath("TestResults/Industrial/creative.xml");if(File.Exists(creativePath))File.Delete(creativePath);if(File.Exists(creativePath+".journal"))File.Delete(creativePath+".journal");var creativeJournal=new IndustrialWorld();creativeJournal.Register(1,new FramePose{body=1}).inventory.items.Clear();using(var authority=new IndustrialAuthority(creativeJournal,creativePath)){authority.Save();authority.Execute(1,C(1,"creative",count:1));authority.Execute(1,C(2,"place",definition:"foundry"));}var recoveredCreative=IndustrialAuthority.Load(creativePath);Check(recoveredCreative.creativeMode&&recoveredCreative.machines.Count==1&&recoveredCreative.Actor(1).inventory.Used==0,"Crash replay preserves free construction and its creative setting");
 string legacyPath=Path.GetFullPath("TestResults/Industrial/legacy-place.xml");if(File.Exists(legacyPath))File.Delete(legacyPath);if(File.Exists(legacyPath+".journal"))File.Delete(legacyPath+".journal");var legacy=new IndustrialWorld();legacy.Register(1,new FramePose{body=1});using(var authority=new IndustrialAuthority(legacy,legacyPath))authority.Save();var oldEntry=new IndustrialJournalEntry{serial=1,actor=1,actorPose=new FramePose{body=1},command=C(1,"place",definition:"foundry")};using(var text=new StringWriter()){new System.Xml.Serialization.XmlSerializer(typeof(IndustrialJournalEntry)).Serialize(text,oldEntry);File.WriteAllText(legacyPath+".journal",Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes(text.ToString()))+"\n");}var migrated=IndustrialAuthority.Load(legacyPath);Check(migrated.machines.Count==1&&migrated.Actor(1).inventory.Count("stone")==52,"Pre-kit journal placement replays at its original paid ingredient cost");

 var contaminated=new IndustrialWorld();var handler=contaminated.Register(1,new FramePose{body=1});handler.inventory.items.Clear();handler.inventory.Add("stone",4,12);Check(contaminated.Execute(1,C(1,"place",definition:"workbench")).accepted&&contaminated.machines[0].constructionActivity==12,"Resource construction retains carried activity");Check(contaminated.Execute(1,C(2,"pack",target:contaminated.machines[0].id)).accepted&&handler.inventory.ActivityOf("stone",4)==12,"Dismantling cannot launder material activity");handler.inventory.Add("iron-bar",2,9);Check(contaminated.Execute(1,C(3,"craft",item:"plate",count:1)).accepted,"Contaminated metal can enter component crafting");for(int t=0;t<15;t++)contaminated.Step();Check(handler.inventory.ActivityOf("plate",2)==9,"Component fabrication preserves material activity");
 var queuedWorld=new IndustrialWorld();var queuedActor=queuedWorld.Register(1,new FramePose{body=1});queuedActor.inventory.Add("iron-bar",20);Check(queuedWorld.Execute(1,C(1,"craft",item:"plate",count:3)).accepted&&queuedActor.craftQueue.Count==2&&queuedActor.inventory.reserved==6&&queuedActor.inventory.Count("iron-bar")==14,"Batch crafting reserves all metal and queued outputs");long queuedId=queuedActor.craftQueue[1].id;Check(queuedWorld.Execute(1,C(2,"cancel-craft",target:queuedId)).accepted&&queuedActor.craftQueue.Count==1&&queuedActor.inventory.Count("iron-bar")==16&&queuedActor.inventory.reserved==4,"Cancelling a selected queued job refunds only that job");Check(!queuedWorld.Execute(1,C(3,"cancel-craft",target:queuedId)).accepted,"A stale cancel cannot remove another job");var queueReloaded=IndustrialAuthority.Restore(IndustrialAuthority.Snapshot(queuedWorld));for(int t=0;t<30;t++)queueReloaded.Step();Check(queueReloaded.Actor(1).inventory.Count("plate")==4&&queueReloaded.Actor(1).inventory.reserved==0&&queueReloaded.Actor(1).craft==null,"Queued component crafts survive reload and finish once");
 var fullQueue=new IndustrialWorld();var q=fullQueue.Register(1,new FramePose{body=1});q.inventory.Add("iron-bar",500);Check(fullQueue.Execute(1,C(1,"craft",item:"plate",count:20)).accepted&&fullQueue.Execute(1,C(2,"craft",item:"plate",count:12)).accepted&&!fullQueue.Execute(1,C(3,"craft",item:"plate",count:1)).accepted,"Queue limit rejects excess jobs without spending ingredients");long beforeCancel=q.inventory.Count("iron-bar");Check(fullQueue.Execute(1,C(3,"cancel-craft",target:q.craft.id)).accepted&&q.craft!=null&&q.inventory.Count("iron-bar")==beforeCancel+2,"Cancelling the active job starts the next without refunding it");
 var oldCraftWorld=new IndustrialWorld();var oldCrafter=oldCraftWorld.Register(1,new FramePose{body=1});oldCrafter.inventory.Remove("stone",4);oldCrafter.inventory.reserved=1;oldCrafter.craft=new IndustrialCraftJob{recipe="workbench-kit",inputs=new System.Collections.Generic.List<ItemStack>{new ItemStack("stone",4)},outputs=new System.Collections.Generic.List<ItemStack>{new ItemStack("workbench-kit",1)}};string oldCraftPath=Path.GetFullPath("TestResults/Industrial/old-craft.xml");if(File.Exists(oldCraftPath))File.Delete(oldCraftPath);if(File.Exists(oldCraftPath+".journal"))File.Delete(oldCraftPath+".journal");using(var authority=new IndustrialAuthority(oldCraftWorld,oldCraftPath)){authority.Save();oldCraftWorld.Register(1,oldCrafter.pose);Check(oldCrafter.craft.id==-1&&authority.Execute(1,C(1,"cancel-craft",target:-1)).accepted,"Legacy active crafts receive a stable cancellation ID");}Check(IndustrialAuthority.Load(oldCraftPath).Actor(1).inventory.Count("stone")==64,"Legacy craft ID migration remains consistent during crash-journal replay");

